using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using System.Web.Script.Serialization;
class ArchiveUiTests {
 static int checks,failures;static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).GetValue(o);}static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,args);}static void Check(bool ok,string n){checks++;Console.WriteLine((ok?"PASS ":"FAIL ")+n);if(!ok)failures++;}static IEnumerable<DependencyObject> Tree(DependencyObject o){yield return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var c in Tree(VisualTreeHelper.GetChild(o,i)))yield return c;}static T Named<T>(DependencyObject o,string n)where T:DependencyObject{return Tree(o).OfType<T>().FirstOrDefault(c=>System.Windows.Automation.AutomationProperties.GetName(c)==n);}static void Pump(){var f=new DispatcherFrame();var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};t.Tick+=(s,e)=>{t.Stop();f.Continue=false;};t.Start();Dispatcher.PushFrame(f);}static void Click(Window w,string caption){Tree(w).OfType<Button>().First(b=>Convert.ToString(b.Content)==caption).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}static void Toggle(Window w,string label,bool value){var c=Tree(w).OfType<CheckBox>().First(b=>Convert.ToString(b.Content)==label);c.IsChecked=value;c.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));Pump();}static void Shot(Window w,string path){w.UpdateLayout();var root=(FrameworkElement)w.Content;var bitmap=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(root);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(bitmap));using(var f=File.Create(path))e.Save(f);}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;try{pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);var assistant=(AssistantRuntime)Get(pet,"assistant");assistant.Config.Monitor.Quota.Enabled=false;((VoiceRuntime)Get(pet,"voices")).Settings.Enabled=false;pet.Show();Pump();((System.Threading.Timer)Get(pet,"assistantTimer")).Change(-1,-1);((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();Call(pet,"OpenTerminal");var w=(TerminalWindow)Get(pet,"terminal");w.Width=1360;w.Height=980;Check(!((Expander)Get(w,"utilityNav")).IsExpanded,"infrequent tools collapsed by default");w.ShowPage("便签");Check(((Expander)Get(w,"utilityNav")).IsExpanded,"opening tool expands its navigation");
 w.ShowPage("任务栏外观");Pump();foreach(string tab in new[]{"项目与排序","布局与屏幕","文字样式","占用条","配色设计","单位与格式"})Check(Tree(w).OfType<Button>().Any(b=>Convert.ToString(b.Content)==tab),"taskbar responsibility tab "+tab);Check(!Tree(w).OfType<Button>().Any(b=>new[]{"逐项渐变","占用图配色","单位与占用图","排序"}.Contains(Convert.ToString(b.Content))),"old overlapping tabs removed");Click(w,"配色设计");var colorBar=Named<UsageRampBar>(w,"可编辑配色条");string barStart=((MonitorConfig)Get(w,"taskbarDraft")).Appearance.Item("cpu").UsageRamp.Stops[0].Color;Named<TextBox>(w,"配色颜色点颜色").Text="#33AAFF";Check(((MonitorConfig)Get(w,"taskbarDraft")).Appearance.Item("cpu").UsageRamp.Stops[0].Color==barStart,"text color edits cannot modify usage ramp");Named<ComboBox>(w,"配色对象").SelectedIndex=2;Pump();Check(Named<TextBox>(w,"占用条颜色")==null,"usage ramp is sole bar color editor");Named<ComboBox>(w,"配色预设").SelectedItem="薄荷警戒";Named<ComboBox>(w,"配色对象").SelectedIndex=3;Pump();Named<TextBox>(w,"配色颜色点颜色").Text="#552299";Click(w,"应用并保存任务栏外观");Check(assistant.Config.Monitor.Appearance.BackgroundRamp.Stops[0].Color=="#552299"&&assistant.Config.Monitor.Appearance.LabelRamp.Stops[0].Color!="#552299","background and text color ramps persist separately");Shot(w,Path.Combine(args[0],"taskbar-background.png"));Click(w,"占用条");Shot(w,Path.Combine(args[0],"taskbar-bars.png"));
 typeof(AssistantRuntime).GetField("Archive").SetValue(assistant,new MonitorArchive(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"fixture-archive")));var today=new DateTime(2026,10,23);assistant.Config.Monitor.Days=Enumerable.Range(1,23).Select(i=>new TrafficDay{Day=new DateTime(2026,10,i).ToString("yyyy-MM-dd"),Download=i*23000000d,Upload=i*3200000d}).ToList();for(int i=1;i<=23;i++){var date=new DateTime(2026,10,i,12,0,0,DateTimeKind.Utc);for(int second=0;second<3;second++)assistant.Archive.Observe(new SystemSample{Utc=date.AddSeconds(second),Cpu=20+(i*11)%75,Gpu=10+(i*17)%85,MemoryUsed=8+i%7,MemoryTotal=32,CpuTemperature=40+i%18,GpuTemperature=35+i%24,DiskTemperature=32+i%7,VramUsed=1024+i%8*300,VramTotal=8192,Download=i*1048576,Upload=i*20000,CpuMHz=3000+i*10,DiskBusy=i%9*8,DiskRead=i,DiskWrite=i/2d,NetworkId="fixture"});assistant.Archive.AddSplit(date,i*10000000,i*1000000,i*22000000,i*1500000,i*300000);var evt=new JavaScriptSerializer().Serialize(new{timestamp=date.ToString("o"),type="event_msg",payload=new{type="token_count",info=new{total_token_usage=new{input_tokens=i*10000,cached_input_tokens=i*2000,output_tokens=i*2000,reasoning_output_tokens=i*500,total_tokens=i*12000}}}});assistant.TokenHistory.Consume(evt,"session"+i);}
 w.ShowPage("流量历史");Pump();Check((string)Get(w,"page")=="线索档案馆","legacy traffic entry resolves to new archive");Named<DatePicker>(w,"流量日期").SelectedDate=today;Call(w,"RefreshArchive",true);var traffic=(TrafficChart)Get(w,"trafficChart");Check(traffic.Bars&&traffic.Lines,"network bars and lines initially overlay");Toggle(w,"柱状图",false);Check(!traffic.Bars&&traffic.Lines,"bar layer toggles independently");Toggle(w,"柱状图",true);Toggle(w,"折线图",false);Check(traffic.Bars&&!traffic.Lines,"line layer toggles independently");Toggle(w,"折线图",true);Toggle(w,"上传流量",false);Check(!traffic.ShowUpload&&traffic.ShowDownload,"upload and download independently selectable");Toggle(w,"上传流量",true);Shot(w,Path.Combine(args[0],"archive-network.png"));
 foreach(string tab in new[]{"直连与代理","资源占用","温度记录","资源容量","速率与频率","Codex用量","额度轨迹"}){Click(w,tab);Named<DatePicker>(w,"档案日期").SelectedDate=today;Call(w,"RefreshArchive",true);var plot=(ArchivePlot)Get(w,"archivePlot");Check(plot.Dates.Length==31&&plot.Bars&&plot.Lines,"archive series and overlay tab "+tab);if(tab=="资源占用"){Check(plot.Unit=="%"&&plot.Series.Length==3&&plot.Series[0].Values.Count(v=>v.HasValue)==23,"resource axes share compatible percent units");var donut=(ArchiveDonut)Get(w,"archiveDonut");Check(donut.Slices.Sum(s=>s.Value)>0,"resource pie uses actual sampled duration");}if(tab=="资源容量")Check(plot.Unit=="GiB","capacity has separate unit axis");if(tab=="速率与频率"){Toggle(w,"CPU频率",true);plot=(ArchivePlot)Get(w,"archivePlot");Check(plot.Unit=="MHz"&&plot.Series.Length==1,"frequency cannot mix with speed axis");}if(tab=="Codex用量"){var donut=(ArchiveDonut)Get(w,"archiveDonut");Check(donut.Slices.Length==3&&plot.Unit=="token","token components do not add reasoning twice");}((TextBlock)Get(w,"archiveSource")).Text="界面验收 · 演示数据 · "+((TextBlock)Get(w,"archiveSource")).Text;Shot(w,Path.Combine(args[0],"archive-"+tab+".png"));}
 Click(w,"采集与来源");Check(Named<TextBox>(w,"本机控制接口")!=null&&Tree(w).OfType<PasswordBox>().Any(),"controller credentials have dedicated protected source editor");Shot(w,Path.Combine(args[0],"archive-sources.png"));w.Close();Call(pet,"OpenTerminal");w=(TerminalWindow)Get(pet,"terminal");w.ShowPage("健康");w.Close();Call(pet,"OpenTerminal");w=(TerminalWindow)Get(pet,"terminal");w.ShowPage("健康");Check((string)Get(w,"page")=="侦探备忘录","health details survive close and reopen");
 }catch(Exception e){Console.WriteLine("FAIL "+e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"archive-ui-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,chart_data="synthetic fixtures",real_controller_connected=false}));return failures==0?0:1;}
